DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "10fab705-da9f-6719-ec0d-3297d5afae40", "before": {"stem": "Q6. If 3x+2 − 3x = 216, what is the value of x?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 48"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00207", "source": "Full-Subject Revision June 2026, page 48 Q6; rendered source confirms superscripts", "review_note": "Restored the two exponents, removed footer text, checked factorization and substitution.", "release": true, "fields": {"stem": "If \\(3^{x+2}-3^x=216\\), what is the value of \\(x\\)?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "topic": "Exponents, Radicals & Logarithms"}, "explanation": "Factor out \\(3^x\\): \\(3^{x+2}-3^x=3^x(9-1)=8\\cdot3^x=216\\). Hence \\(3^x=27=3^3\\), so \\(x=3\\). Check: \\(3^5-3^3=243-27=216\\).", "correct": "B"}, {"id": "3556fa31-7c75-76db-d8d7-9ee22d7c3867", "before": {"stem": "If 3x+2 − 3x = 216, what is the value of x?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "B", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p48-q214", "source": "Full-Subject Revision June 2026, page 48 Q6; rendered source confirms superscripts", "review_note": "Restored the two exponents, removed footer text, checked factorization and substitution.", "release": true, "fields": {"stem": "If \\(3^{x+2}-3^x=216\\), what is the value of \\(x\\)?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "topic": "Exponents, Radicals & Logarithms"}, "explanation": "Factor out \\(3^x\\): \\(3^{x+2}-3^x=3^x(9-1)=8\\cdot3^x=216\\). Hence \\(3^x=27=3^3\\), so \\(x=3\\). Check: \\(3^5-3^3=243-27=216\\).", "correct": "B"}, {"id": "11bda1e3-466b-3bb2-9f02-0d974eafc9fe", "before": {"stem": "For the same function, if a = 1 and the coefficient of the x² term equals the\ncoefficient of the x³ term, what is the value of b?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2"}], "correct": "C", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p15-q71", "source": "Full-Subject Revision June 2026, page 15 Q70–71", "review_note": "Restored the function shared with Q70 so the item is self-contained.", "release": true, "fields": {"stem": "Let \\(f(x)=3ax^3+4bx^2+x+x^3\\), where \\(a\\) and \\(b\\) are real constants. If \\(a=1\\) and the coefficient of \\(x^2\\) equals the coefficient of \\(x^3\\), what is \\(b\\)?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2"}]}, "explanation": "Collect like powers: \\(f(x)=(3a+1)x^3+4bx^2+x\\). With \\(a=1\\), the coefficient of \\(x^3\\) is 4. Therefore \\(4b=4\\), giving \\(b=1\\).", "correct": "C"}, {"id": "97df8a5e-6024-2d0d-a942-c3cf570530db", "before": {"stem": "Q71. For the same function, if a = 1 and the coefficient of the x² term equals the\n coefficient of the x³ term, what is the value of b?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2 01116004434"}], "correct": "C", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00070", "source": "Full-Subject Revision June 2026, page 15 Q70–71", "review_note": "Restored the function shared with Q70 so the item is self-contained.", "release": true, "fields": {"stem": "Let \\(f(x)=3ax^3+4bx^2+x+x^3\\), where \\(a\\) and \\(b\\) are real constants. If \\(a=1\\) and the coefficient of \\(x^2\\) equals the coefficient of \\(x^3\\), what is \\(b\\)?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2"}]}, "explanation": "Collect like powers: \\(f(x)=(3a+1)x^3+4bx^2+x\\). With \\(a=1\\), the coefficient of \\(x^3\\) is 4. Therefore \\(4b=4\\), giving \\(b=1\\).", "correct": "C"}, {"id": "97c00f1c-f888-4ff6-b111-478c90998768", "before": {"stem": "For the same plants (mean = 18 cm), 3 new plants are added and the new\nmean becomes 17 cm. Which could be the heights of the new plants?", "choices": [{"key": "A", "text": "10, 13, 14 cm"}, {"key": "B", "text": "10, 13, 17 cm"}, {"key": "C", "text": "10, 14, 15 cm"}, {"key": "D", "text": "10, 15, 16 cm"}], "correct": "D", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p44-q203", "source": "Full-Subject Revision June 2026, page 44 Q49–50", "review_note": "Restored the ten-plant sample size from Q49; checked the new total.", "release": true, "fields": {"stem": "Ten plants have a mean height of 18 cm. Three plants are added, and the mean height of all 13 plants becomes 17 cm. Which could be the heights of the three added plants?"}, "explanation": "The original total height is \\(10\\times18=180\\) cm. The new total is \\(13\\times17=221\\) cm. The three added heights must sum to \\(221-180=41\\) cm. Only \\(10+15+16=41\\), so D is correct.", "correct": "D"}, {"id": "8a2ed657-7340-f2c3-118f-fa2205210590", "before": {"stem": "Using the same table, what is P(boy | local)?", "choices": [{"key": "A", "text": "0.265"}, {"key": "B", "text": "0.316"}, {"key": "C", "text": "0.447"}, {"key": "D", "text": "0.638"}], "correct": "C", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p39-q178", "source": "Full-Subject Revision June 2026, page 39 Q24–25", "review_note": "Restored the full two-way table and checked the conditional denominator.", "release": true, "fields": {"stem": "A school has 101 local boys, 60 expatriate boys, 125 local girls, and 34 expatriate girls. If a student is chosen at random from the local students, what is the probability that the student is a boy, to three decimal places?", "choices": [{"key": "A", "text": "0.265"}, {"key": "B", "text": "0.316"}, {"key": "C", "text": "0.447"}, {"key": "D", "text": "0.638"}]}, "explanation": "Restrict the sample to local students: there are \\(101+125=226\\). Of these, 101 are boys. Thus \\(P(\\text{boy}\\mid\\text{local})=101/226\\approx0.447\\), choice C.", "correct": "C"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;

