BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "ef282e93-a54f-4da9-8955-3f079623b2e9", "before": {"stem": "A scatterplot shows the relationship between the number of swans, $y$, in a certain population and the number of years since 1970, $x$, where $0\\le x\\le50$. Which of the following equations is the most appropriate exponential model for the data shown in the scatterplot?", "choices": [{"key": "A", "text": "$y=43(1.04)^{-x}$"}, {"key": "B", "text": "$y=43(1.04)^x$"}, {"key": "C", "text": "$y=288(1.04)^{-x}$"}, {"key": "D", "text": "$y=288(1.04)^x$"}], "correct": "B", "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$."}, "source_question_id": null, "source": "Original stored College Board figure CB-dbd89c59; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$.", "correct": "B", "figure_from_id": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a", "duplicate_of": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a"}, {"id": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a", "before": {"stem": "A scatterplot shows the relationship between the number of swans, $y$, in a certain population and the number of years since 1970, $x$, where $0\\le x\\le50$. Which of the following equations is the most appropriate exponential model for the data shown in the scatterplot?", "choices": [{"key": "A", "text": "$y=43(1.04)^{-x}$"}, {"key": "B", "text": "$y=43(1.04)^x$"}, {"key": "C", "text": "$y=288(1.04)^{-x}$"}, {"key": "D", "text": "$y=288(1.04)^x$"}], "correct": "B", "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$."}, "source_question_id": null, "source": "Original stored College Board figure CB-dbd89c59; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$.", "correct": "B", "figure_from_id": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a"}, {"id": "4bf880f3-dbf0-52f5-43de-7452a7cf5d71", "before": {"stem": "Question 2. If 𝑝−3𝑞 + 𝑞 = 2𝑝+𝑞 − 11, then the value of 𝑝 in terms of 𝑞 is:\n 4 2 2 4", "choices": [{"key": "A", "text": "− 1 11 5𝑞− 5"}, {"key": "B", "text": "− 1 11 5𝑞+ 5"}, {"key": "C", "text": "−𝑞+ 11\n 3"}, {"key": "D", "text": "3 11 5𝑞− 5"}, {"key": "E", "text": "𝑞+ 11\n 3\n\n 𝑥2+4"}], "correct": "C", "explanation": "Multiplying the printed equation by 4 gives p-3q+2q=4p+2q-11. Thus 3p=11-3q and p=-q+11/3."}, "source_question_id": "est2_hs_level1_jan_2026-q00262", "source": "ESTII-HS Math L1 January 2026 Q2; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(\\frac{p-3q}{4}+\\frac q2=\\frac{2p+q}{2}-\\frac{11}4\\), which expression gives p in terms of q?", "choices": [{"key": "A", "text": "\\(-\\frac1{5q}-\\frac{11}5\\)"}, {"key": "B", "text": "\\(-\\frac1{5q}+\\frac{11}5\\)"}, {"key": "C", "text": "\\(-q+\\frac{11}3\\)"}, {"key": "D", "text": "\\(\\frac3{5q}-\\frac{11}5\\)"}, {"key": "E", "text": "\\(q+\\frac{11}3\\)"}]}, "explanation": "Multiply by 4: p − 3q + 2q = 4p + 2q − 11. Rearranging gives 3p = 11 − 3q, so \\(p=-q+11/3\\).", "correct": "C"}, {"id": "7b2c3532-d0ee-b299-918e-63be6138078f", "before": {"stem": "Question 3. Let 𝑔(𝑥) = −4𝑥2−5𝑥+6. For which values of 𝑥 is 𝑔(𝑥) undefined?", "choices": [{"key": "A", "text": "𝑥= −2 and 𝑥= − 3\n 4"}, {"key": "B", "text": "𝑥= −2 and 𝑥= 3\n 4"}, {"key": "C", "text": "𝑥= 2 and 𝑥= − 3\n 4"}, {"key": "D", "text": "𝑥= 2 and 𝑥= 3\n 4"}, {"key": "E", "text": "𝑥= 2 and 𝑥= 4\n 3"}], "correct": "B", "explanation": "The denominator factors as -4x^2-5x+6=-(4x-3)(x+2). It is zero at x=3/4 and x=-2."}, "source_question_id": "est2_hs_level1_jan_2026-q00263", "source": "ESTII-HS Math L1 January 2026 Q3; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "For which x-values is \\(g(x)=\\frac{x^2+4}{-4x^2-5x+6}\\) undefined?", "choices": [{"key": "A", "text": "\\(x=-2\\) and \\(x=-3/4\\)"}, {"key": "B", "text": "\\(x=-2\\) and \\(x=3/4\\)"}, {"key": "C", "text": "\\(x=2\\) and \\(x=-3/4\\)"}, {"key": "D", "text": "\\(x=2\\) and \\(x=3/4\\)"}, {"key": "E", "text": "\\(x=2\\) and \\(x=4/3\\)"}], "topic": "Rational, Radical, Exponential & Logarithmic Functions"}, "explanation": "The denominator factors as \\(-4x^2-5x+6=-(4x-3)(x+2)\\). It is zero at x = 3/4 and x = −2. The numerator is positive for every real x, so neither point is removable from the original domain.", "correct": "B"}, {"id": "a0633725-f7d2-ead0-4cc8-e38ca24310e0", "before": {"stem": "Question 4. Consider a line 𝑑 of equation 2𝑦= 3𝑥+ 5. Line 𝐿 is perpendicular to 𝑑, and 𝑇 is\n a line parallel to 𝐿. If 𝐴(−5, 3) is a point on 𝑇, then the equation of 𝑇 is:", "choices": [{"key": "A", "text": "2𝑦−3𝑥= 1"}, {"key": "B", "text": "3𝑦−2𝑥= −3"}, {"key": "C", "text": "3𝑦−2𝑥= −1"}, {"key": "D", "text": "3𝑦+ 2𝑥= −1"}, {"key": "E", "text": "3𝑦+ 2𝑥= 3\n\n 3\nESTII-HS Math L1 January 2026"}], "correct": "D", "explanation": "The given line has slope 3/2, so T has slope -2/3. Passing through (-5,3) gives 3y+2x=-1."}, "source_question_id": "est2_hs_level1_jan_2026-q00264", "source": "ESTII-HS Math L1 January 2026 Q4; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Line d has equation 2y = 3x + 5. Line L is perpendicular to d, and line T is parallel to L. If T passes through (−5, 3), which is its equation?", "choices": [{"key": "A", "text": "2y − 3x = 1"}, {"key": "B", "text": "3y − 2x = −3"}, {"key": "C", "text": "3y − 2x = −1"}, {"key": "D", "text": "3y + 2x = −1"}, {"key": "E", "text": "3y + 2x = 3"}]}, "explanation": "Line d has slope 3/2, so L and T have slope −2/3. Using (−5, 3), y − 3 = (−2/3)(x + 5). Multiplying by 3 and rearranging gives 3y + 2x = −1.", "correct": "D"}, {"id": "c30642f4-b2c8-4264-9725-32c3cbd3e2d1", "before": {"stem": "Question 4. Line d has equation 2y = 3x + 5. Line L is perpendicular to d, and T is parallel to L. If A(−5, 3) lies on T, what is the equation of T?", "choices": [{"key": "A", "text": "2y − 3x = 1"}, {"key": "B", "text": "3y − 2x = −3"}, {"key": "C", "text": "3y − 2x = −1"}, {"key": "D", "text": "3y + 2x = −1"}, {"key": "E", "text": "3y + 2x = 3"}], "correct": "D", "explanation": "The given line has slope 3/2, so T has slope -2/3. Passing through (-5,3) gives 3y+2x=-1."}, "source_question_id": "est2_hs_level1_jan_2026-q00004", "source": "ESTII-HS Math L1 January 2026 Q4; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Line d has equation 2y = 3x + 5. Line L is perpendicular to d, and line T is parallel to L. If T passes through (−5, 3), which is its equation?", "choices": [{"key": "A", "text": "2y − 3x = 1"}, {"key": "B", "text": "3y − 2x = −3"}, {"key": "C", "text": "3y − 2x = −1"}, {"key": "D", "text": "3y + 2x = −1"}, {"key": "E", "text": "3y + 2x = 3"}]}, "explanation": "Line d has slope 3/2, so L and T have slope −2/3. Using (−5, 3), y − 3 = (−2/3)(x + 5). Multiplying by 3 and rearranging gives 3y + 2x = −1.", "correct": "D"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;

-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "b4ccfdf3-7c73-7a09-a5b8-e77f416a53ba", "before": {"stem": "Question 5. In a geometric sequence, the 5th term is 3,200,000 and the 10th term is 1,024. What\n is the first term of this sequence?", "choices": [{"key": "A", "text": "2 × 109"}, {"key": "B", "text": "2 × 1010"}, {"key": "C", "text": "2 × 1011"}, {"key": "D", "text": "2 × 1016"}, {"key": "E", "text": "2 × 1020\n\n 15, 16, 17, 𝑦, 20, 21, 24, 20"}], "correct": "A", "explanation": "The common ratio satisfies r^5=1024/3200000=1/3125=(1/5)^5. The first term is a5/r^4=3200000*625=2*10^9."}, "source_question_id": "est2_hs_level1_jan_2026-q00265", "source": "ESTII-HS Math L1 January 2026 Q5; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "In a geometric sequence, the fifth term is 3,200,000 and the tenth term is 1,024. What is the first term?", "choices": [{"key": "A", "text": "\\(2\\times10^9\\)"}, {"key": "B", "text": "\\(2\\times10^{10}\\)"}, {"key": "C", "text": "\\(2\\times10^{11}\\)"}, {"key": "D", "text": "\\(2\\times10^{16}\\)"}, {"key": "E", "text": "\\(2\\times10^{20}\\)"}]}, "explanation": "For common ratio r, \\(r^5=1024/3200000=1/3125=(1/5)^5\\), so the real ratio is r = 1/5. Thus \\(a_1=a_5/r^4=3200000\\times625=2\\times10^9\\).", "correct": "A"}, {"id": "f33db1e8-904a-4e5a-8702-f1a73a45fb8d", "before": {"stem": "Question 5. In a geometric sequence, the 5th term is 3,200,000 and the 10th term is 1,024. What is the first term?", "choices": [{"key": "A", "text": "2 × 10⁹"}, {"key": "B", "text": "2 × 10¹⁰"}, {"key": "C", "text": "2 × 10¹¹"}, {"key": "D", "text": "2 × 10¹⁶"}, {"key": "E", "text": "2 × 10²⁰"}], "correct": "A", "explanation": "The common ratio satisfies r^5=1024/3200000=1/3125=(1/5)^5. The first term is a5/r^4=3200000*625=2*10^9."}, "source_question_id": "est2_hs_level1_jan_2026-q00005", "source": "ESTII-HS Math L1 January 2026 Q5; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "In a geometric sequence, the fifth term is 3,200,000 and the tenth term is 1,024. What is the first term?", "choices": [{"key": "A", "text": "\\(2\\times10^9\\)"}, {"key": "B", "text": "\\(2\\times10^{10}\\)"}, {"key": "C", "text": "\\(2\\times10^{11}\\)"}, {"key": "D", "text": "\\(2\\times10^{16}\\)"}, {"key": "E", "text": "\\(2\\times10^{20}\\)"}]}, "explanation": "For common ratio r, \\(r^5=1024/3200000=1/3125=(1/5)^5\\), so the real ratio is r = 1/5. Thus \\(a_1=a_5/r^4=3200000\\times625=2\\times10^9\\).", "correct": "A"}, {"id": "913feccc-10f8-4777-e5a5-793fe176bf59", "before": {"stem": "Question 7. Which of the following functions is the inverse of function 𝑝 defined by\n 𝑥−1\n 𝑝(𝑥) = 𝑥+2?", "choices": [{"key": "A", "text": "𝑝−1(𝑥) = 2𝑥\n 1−𝑥"}, {"key": "B", "text": "𝑝−1(𝑥) = 𝑥−1\n 2𝑥−1"}, {"key": "C", "text": "𝑝−1(𝑥) = 2𝑥−1\n 𝑥+1"}, {"key": "D", "text": "𝑝−1(𝑥) = 1−2𝑥\n 1−𝑥"}, {"key": "E", "text": "𝑝−1(𝑥) = 2𝑥+1\n 1−𝑥"}], "correct": "E", "explanation": "Set y=(x-1)/(x+2). Solving yx+2y=x-1 gives x=(2y+1)/(1-y), so p inverse is (2x+1)/(1-x)."}, "source_question_id": "est2_hs_level1_jan_2026-q00267", "source": "ESTII-HS Math L1 January 2026 Q7; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(p(x)=\\frac{x-1}{x+2}\\), which expression is its inverse function?", "choices": [{"key": "A", "text": "\\(p^{-1}(x)=\\frac{2x}{1-x}\\)"}, {"key": "B", "text": "\\(p^{-1}(x)=\\frac{x-1}{2x-1}\\)"}, {"key": "C", "text": "\\(p^{-1}(x)=\\frac{2x-1}{x+1}\\)"}, {"key": "D", "text": "\\(p^{-1}(x)=\\frac{1-2x}{1-x}\\)"}, {"key": "E", "text": "\\(p^{-1}(x)=\\frac{2x+1}{1-x}\\)"}]}, "explanation": "Write \\(y=(x-1)/(x+2)\\). Then yx + 2y = x − 1, so x(y − 1) = −1 − 2y and \\(x=(2y+1)/(1-y)\\). Interchanging the variables gives \\(p^{-1}(x)=(2x+1)/(1-x)\\), with x ≠ 1.", "correct": "E"}, {"id": "207b8ccc-eaeb-2ddb-d818-e9d661d2d10d", "before": {"stem": "Question 15. Given an equilateral triangle 𝑀𝑁𝑃 such that 𝑀𝑃= 𝑀𝑁= (2𝑥−5) 𝑐𝑚 and\n 𝑁𝑃= (𝑥+ 2) 𝑐𝑚, the area of ∆𝑀𝑁𝑃 is:", "choices": [{"key": "A", "text": "81 √3 𝑐𝑚2\n 2"}, {"key": "B", "text": "81 √3 𝑐𝑚2\n 4"}, {"key": "C", "text": "81 √3 𝑐𝑚2\n 8"}, {"key": "D", "text": "9 √3 𝑐𝑚2\n 2"}, {"key": "E", "text": "9 √3 𝑐𝑚2\n 4\n\n 6\nESTII-HS Math L1 January 2026"}], "correct": "B", "explanation": "Equilateral sides require 2x-5=x+2, so x=7 and side 9. Its area is (sqrt(3)/4)(9^2)=81sqrt(3)/4."}, "source_question_id": "est2_hs_level1_jan_2026-q00275", "source": "ESTII-HS Math L1 January 2026 Q15; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "An equilateral triangle MNP has MP = MN = (2x − 5) cm and NP = (x + 2) cm. What is its area?", "choices": [{"key": "A", "text": "\\(\\frac{81\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "B", "text": "\\(\\frac{81\\sqrt3}{4}\\text{ cm}^2\\)"}, {"key": "C", "text": "\\(\\frac{81\\sqrt3}{8}\\text{ cm}^2\\)"}, {"key": "D", "text": "\\(\\frac{9\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "E", "text": "\\(\\frac{9\\sqrt3}{4}\\text{ cm}^2\\)"}]}, "explanation": "Equal sides give 2x − 5 = x + 2, so x = 7 and the side length is 9 cm. An equilateral triangle has area \\(s^2\\sqrt3/4\\), hence \\(81\\sqrt3/4\\) square centimeters.", "correct": "B"}, {"id": "8cef0778-f1c1-4adf-8980-efff0903e649", "before": {"stem": "Question 15. An equilateral triangle has two sides of length (2x − 5) cm and a third side of length (x + 2) cm. Find its area.", "choices": [{"key": "A", "text": "81√3/2 cm²"}, {"key": "B", "text": "81√3/4 cm²"}, {"key": "C", "text": "81√3/8 cm²"}, {"key": "D", "text": "9√3/2 cm²"}, {"key": "E", "text": "9√3/4 cm²"}], "correct": "B", "explanation": "Equilateral sides require 2x-5=x+2, so x=7 and side 9. Its area is (sqrt(3)/4)(9^2)=81sqrt(3)/4."}, "source_question_id": "est2_hs_level1_jan_2026-q00015", "source": "ESTII-HS Math L1 January 2026 Q15; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "An equilateral triangle MNP has MP = MN = (2x − 5) cm and NP = (x + 2) cm. What is its area?", "choices": [{"key": "A", "text": "\\(\\frac{81\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "B", "text": "\\(\\frac{81\\sqrt3}{4}\\text{ cm}^2\\)"}, {"key": "C", "text": "\\(\\frac{81\\sqrt3}{8}\\text{ cm}^2\\)"}, {"key": "D", "text": "\\(\\frac{9\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "E", "text": "\\(\\frac{9\\sqrt3}{4}\\text{ cm}^2\\)"}]}, "explanation": "Equal sides give 2x − 5 = x + 2, so x = 7 and the side length is 9 cm. An equilateral triangle has area \\(s^2\\sqrt3/4\\), hence \\(81\\sqrt3/4\\) square centimeters.", "correct": "B"}, {"id": "4fddd491-c71b-4ecd-a375-c7d11ddf4e56", "before": {"stem": "Question 18. Let f(x) = x³ − 3, g(x) = 4x² + 1, and h(x) = x. Find (g ∘ f ∘ h)(x).", "choices": [{"key": "A", "text": "4x⁶ + 24x³ + 36"}, {"key": "B", "text": "4x⁶ − 24x³ + 37"}, {"key": "C", "text": "4x⁵ + 24x³ − 37"}, {"key": "D", "text": "4x⁵ + 18x³ + 36"}, {"key": "E", "text": "4x⁵ − 18x³ + 1"}], "correct": "B", "explanation": "g(f(h(x)))=4(x^3-3)^2+1=4x^6-24x^3+37."}, "source_question_id": "est2_hs_level1_jan_2026-q00018", "source": "ESTII-HS Math L1 January 2026 Q18; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(f(x)=x^3-3\\), \\(g(x)=4x^2+1\\), and \\(h(x)=x\\), what is \\((g\\circ f\\circ h)(x)\\)?", "choices": [{"key": "A", "text": "\\(4x^6+24x^3+36\\)"}, {"key": "B", "text": "\\(4x^6-24x^3+37\\)"}, {"key": "C", "text": "\\(4x^5+24x^3-37\\)"}, {"key": "D", "text": "\\(4x^5+18x^3+36\\)"}, {"key": "E", "text": "\\(4x^5-18x^3+1\\)"}]}, "explanation": "First \\(f(h(x))=x^3-3\\). Then \\(g(f(h(x)))=4(x^3-3)^2+1=4(x^6-6x^3+9)+1=4x^6-24x^3+37\\).", "correct": "B"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;

