DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "9094100b-200e-ee40-5c3d-b164b2033f70", "before": {"stem": "Question 18. If 𝑓, 𝑔, and ℎ are three functions defined by 𝑓(𝑥) = 𝑥3 −3, 𝑔(𝑥) = 4𝑥2 + 1, and\n ℎ(𝑥) = 𝑥, then (𝑔∘𝑓∘ℎ)(𝑥) =", "choices": [{"key": "A", "text": "4𝑥6 + 24𝑥3 + 36"}, {"key": "B", "text": "4𝑥6 −24𝑥3 + 37"}, {"key": "C", "text": "4𝑥5 + 24𝑥3 −37"}, {"key": "D", "text": "4𝑥5 + 18𝑥3 + 36"}, {"key": "E", "text": "4𝑥5 −18𝑥3 + 1\n\n 7\nESTII-HS Math L1 January 2026"}], "correct": "B", "explanation": "g(f(h(x)))=4(x^3-3)^2+1=4x^6-24x^3+37."}, "source_question_id": "est2_hs_level1_jan_2026-q00278", "source": "ESTII-HS Math L1 January 2026 Q18; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(f(x)=x^3-3\\), \\(g(x)=4x^2+1\\), and \\(h(x)=x\\), what is \\((g\\circ f\\circ h)(x)\\)?", "choices": [{"key": "A", "text": "\\(4x^6+24x^3+36\\)"}, {"key": "B", "text": "\\(4x^6-24x^3+37\\)"}, {"key": "C", "text": "\\(4x^5+24x^3-37\\)"}, {"key": "D", "text": "\\(4x^5+18x^3+36\\)"}, {"key": "E", "text": "\\(4x^5-18x^3+1\\)"}]}, "explanation": "First \\(f(h(x))=x^3-3\\). Then \\(g(f(h(x)))=4(x^3-3)^2+1=4(x^6-6x^3+9)+1=4x^6-24x^3+37\\).", "correct": "B"}, {"id": "20cedb1e-7d26-a359-c7c9-b50c387751bc", "before": {"stem": "Question 19. A simplified form of the expression × is:\n 3 4", "choices": [{"key": "A", "text": "5 sin(𝑥) ∙cos(𝑥)\n 3"}, {"key": "B", "text": "cot(𝑥)"}, {"key": "C", "text": "2 tan(𝑥)"}, {"key": "D", "text": "5\n 3"}, {"key": "E", "text": "20\n 3"}], "correct": "D", "explanation": "tan x+cot x=(sin^2 x+cos^2 x)/(sin x cos x)=1/(sin x cos x). Multiplying the printed factors gives 20/(3*4)=5/3."}, "source_question_id": "est2_hs_level1_jan_2026-q00279", "source": "ESTII-HS Math L1 January 2026 Q19; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Simplify \\(\\frac{20\\sin x\\cos x}{3}\\times\\frac{\\tan x+\\cot x}{4}\\), for values of x where the expression is defined.", "choices": [{"key": "A", "text": "\\(\\frac53\\sin x\\cos x\\)"}, {"key": "B", "text": "\\(\\cot x\\)"}, {"key": "C", "text": "\\(2\\tan x\\)"}, {"key": "D", "text": "\\(\\frac53\\)"}, {"key": "E", "text": "\\(\\frac{20}3\\)"}]}, "explanation": "On the domain of the original expression, \\(\\tan x+\\cot x=(\\sin^2x+\\cos^2x)/(\\sin x\\cos x)=1/(\\sin x\\cos x)\\). The product is therefore \\(20/(3\\cdot4)=5/3\\).", "correct": "D"}, {"id": "4b03311e-c655-a42b-07f4-d509b21592f4", "before": {"stem": "Question 19. A simplified form of the expression × is:\n 3 4", "choices": [{"key": "A", "text": "5 sin(𝑥) ∙cos(𝑥)\n 3"}, {"key": "B", "text": "cot(𝑥)"}, {"key": "C", "text": "2 tan(𝑥)"}, {"key": "D", "text": "5\n 3"}, {"key": "E", "text": "20\n 3"}], "correct": "D", "explanation": "tan x+cot x=(sin^2 x+cos^2 x)/(sin x cos x)=1/(sin x cos x). Multiplying the printed factors gives 20/(3*4)=5/3."}, "source_question_id": "est2_hs_level1_jan_2026-q00019", "source": "ESTII-HS Math L1 January 2026 Q19; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": false, "fields": {"stem": "Simplify \\(\\frac{20\\sin x\\cos x}{3}\\times\\frac{\\tan x+\\cot x}{4}\\), for values of x where the expression is defined.", "choices": [{"key": "A", "text": "\\(\\frac53\\sin x\\cos x\\)"}, {"key": "B", "text": "\\(\\cot x\\)"}, {"key": "C", "text": "\\(2\\tan x\\)"}, {"key": "D", "text": "\\(\\frac53\\)"}, {"key": "E", "text": "\\(\\frac{20}3\\)"}]}, "explanation": "On the domain of the original expression, \\(\\tan x+\\cot x=(\\sin^2x+\\cos^2x)/(\\sin x\\cos x)=1/(\\sin x\\cos x)\\). The product is therefore \\(20/(3\\cdot4)=5/3\\).", "correct": "D", "duplicate_of": "20cedb1e-7d26-a359-c7c9-b50c387751bc"}, {"id": "4f1d8e88-f6f9-200e-8112-594ec20c8511", "before": {"stem": "Question 22. 𝐴𝐵𝐶 is a right triangle as shown in the figure above. If 𝐴𝐵= 5𝑥−6 and 𝐵𝐶= 2𝑥,\n which of the following is true if 𝐴𝐵𝐶 is also isosceles? (Figure not drawn to scale)", "choices": [{"key": "A", "text": "𝑥= 6\n 7"}, {"key": "B", "text": "𝑥= 30−6√2\n 23"}, {"key": "C", "text": "𝑥= 6\n 5"}, {"key": "D", "text": "𝑥= 2"}, {"key": "E", "text": "None of the above"}], "correct": "E", "explanation": "A right isosceles triangle has equal legs and hypotenuse 2x. Thus 5x-6=sqrt(2)x, giving x=6/(5-sqrt(2))=(30+6sqrt(2))/23. None of the printed choices matches."}, "source_question_id": "est2_hs_level1_jan_2026-q00282", "source": "ESTII-HS Math L1 January 2026 Q22; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Triangle ABC is right-angled at A, with AB = 5x − 6 and hypotenuse BC = 2x. If the triangle is also isosceles, which statement is true?", "choices": [{"key": "A", "text": "\\(x=6/7\\)"}, {"key": "B", "text": "\\(x=(30-6\\sqrt2)/23\\)"}, {"key": "C", "text": "\\(x=6/5\\)"}, {"key": "D", "text": "x = 2"}, {"key": "E", "text": "None of the above"}]}, "explanation": "In a right isosceles triangle the hypotenuse is √2 times a leg. Thus \\(2x=\\sqrt2(5x-6)\\), or \\(5x-6=\\sqrt2x\\). Solving gives \\(x=6/(5-\\sqrt2)=(30+6\\sqrt2)/23\\). This is positive and produces positive side lengths, but none of A–D equals it.", "correct": "E"}, {"id": "b2178b81-3ecf-63c7-68f3-e45b90c54a7f", "before": {"stem": "Question 22. 𝐴𝐵𝐶 is a right triangle as shown in the figure above. If 𝐴𝐵= 5𝑥−6 and 𝐵𝐶= 2𝑥,\n which of the following is true if 𝐴𝐵𝐶 is also isosceles? (Figure not drawn to scale)", "choices": [{"key": "A", "text": "𝑥= 6\n 7"}, {"key": "B", "text": "𝑥= 30−6√2\n 23"}, {"key": "C", "text": "𝑥= 6\n 5"}, {"key": "D", "text": "𝑥= 2"}, {"key": "E", "text": "None of the above"}], "correct": "E", "explanation": "A right isosceles triangle has equal legs and hypotenuse 2x. Thus 5x-6=sqrt(2)x, giving x=6/(5-sqrt(2))=(30+6sqrt(2))/23. None of the printed choices matches."}, "source_question_id": "est2_hs_level1_jan_2026-q00022", "source": "ESTII-HS Math L1 January 2026 Q22; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Triangle ABC is right-angled at A, with AB = 5x − 6 and hypotenuse BC = 2x. If the triangle is also isosceles, which statement is true?", "choices": [{"key": "A", "text": "\\(x=6/7\\)"}, {"key": "B", "text": "\\(x=(30-6\\sqrt2)/23\\)"}, {"key": "C", "text": "\\(x=6/5\\)"}, {"key": "D", "text": "x = 2"}, {"key": "E", "text": "None of the above"}]}, "explanation": "In a right isosceles triangle the hypotenuse is √2 times a leg. Thus \\(2x=\\sqrt2(5x-6)\\), or \\(5x-6=\\sqrt2x\\). Solving gives \\(x=6/(5-\\sqrt2)=(30+6\\sqrt2)/23\\). This is positive and produces positive side lengths, but none of A–D equals it.", "correct": "E"}, {"id": "76aca08e-6b22-27d6-2ce8-bd56623e5979", "before": {"stem": "Question 23. In the figure above, the area of the shaded part is: (Figure not drawn to scale)", "choices": [{"key": "A", "text": "100𝜋 𝑚2"}, {"key": "B", "text": "250𝜋 𝑚2"}, {"key": "C", "text": "1,000𝜋 𝑚2"}, {"key": "D", "text": "1,250𝜋 𝑚2"}, {"key": "E", "text": "2,500𝜋 𝑚2\n\n 9\nESTII-HS Math L1 January 2026"}], "correct": "E", "explanation": "The 100 m outer-circle chord is tangent to the inner circle at its midpoint. Half the chord is 50 m, so R^2-r^2=50^2. The shaded annulus area is pi(R^2-r^2)=2500pi square meters."}, "source_question_id": "est2_hs_level1_jan_2026-q00283", "source": "ESTII-HS Math L1 January 2026 Q23; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Two concentric circles form the shaded annulus shown. A chord of the outer circle is 100 m long and is tangent to the inner circle. What is the shaded area?", "choices": [{"key": "A", "text": "\\(100\\pi\\text{ m}^2\\)"}, {"key": "B", "text": "\\(250\\pi\\text{ m}^2\\)"}, {"key": "C", "text": "\\(1000\\pi\\text{ m}^2\\)"}, {"key": "D", "text": "\\(1250\\pi\\text{ m}^2\\)"}, {"key": "E", "text": "\\(2500\\pi\\text{ m}^2\\)"}]}, "explanation": "The radius to the tangent point is perpendicular to the chord and bisects it. If the radii are R and r, the resulting right triangle gives \\(R^2=r^2+50^2\\). Thus the annulus area is \\(\\pi(R^2-r^2)=2500\\pi\\) square meters.", "correct": "E"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
