 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "92132fbd-b297-9609-9876-5d0acffd190b", "before": {"stem": "Question 23. In the figure above, the area of the shaded part is: (Figure not drawn to scale)", "choices": [{"key": "A", "text": "100𝜋 𝑚2"}, {"key": "B", "text": "250𝜋 𝑚2"}, {"key": "C", "text": "1,000𝜋 𝑚2"}, {"key": "D", "text": "1,250𝜋 𝑚2"}, {"key": "E", "text": "2,500𝜋 𝑚2\n\n 9\nESTII-HS Math L1 January 2026"}], "correct": "E", "explanation": "The 100 m outer-circle chord is tangent to the inner circle at its midpoint. Half the chord is 50 m, so R^2-r^2=50^2. The shaded annulus area is pi(R^2-r^2)=2500pi square meters."}, "source_question_id": "est2_hs_level1_jan_2026-q00023", "source": "ESTII-HS Math L1 January 2026 Q23; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Two concentric circles form the shaded annulus shown. A chord of the outer circle is 100 m long and is tangent to the inner circle. What is the shaded area?", "choices": [{"key": "A", "text": "\\(100\\pi\\text{ m}^2\\)"}, {"key": "B", "text": "\\(250\\pi\\text{ m}^2\\)"}, {"key": "C", "text": "\\(1000\\pi\\text{ m}^2\\)"}, {"key": "D", "text": "\\(1250\\pi\\text{ m}^2\\)"}, {"key": "E", "text": "\\(2500\\pi\\text{ m}^2\\)"}]}, "explanation": "The radius to the tangent point is perpendicular to the chord and bisects it. If the radii are R and r, the resulting right triangle gives \\(R^2=r^2+50^2\\). Thus the annulus area is \\(\\pi(R^2-r^2)=2500\\pi\\) square meters.", "correct": "E"}, {"id": "a35f72ba-7401-6ab9-98fa-2ff0adeca6e8", "before": {"stem": "Question 30. One employee is randomly selected from the company. What is the probability that\n the employee is a man with an annual salary of at least $11,000?", "choices": [{"key": "A", "text": "4\n 25"}, {"key": "B", "text": "32\n 132"}, {"key": "C", "text": "50\n 132"}, {"key": "D", "text": "32\n 55"}, {"key": "E", "text": "35\n 55"}], "correct": "A", "explanation": "The male employees earning at least $11,000 are 20 in [11,13) and 12 in [13,15), or 32 out of 200 employees. Probability 32/200=4/25."}, "source_question_id": "est2_hs_level1_jan_2026-q00290", "source": "ESTII-HS Math L1 January 2026 Q30; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "The table gives annual salaries for all 200 employees in a company. One employee is selected at random. What is the probability that the employee is a man earning at least $11,000 per year?", "choices": [{"key": "A", "text": "4/25"}, {"key": "B", "text": "32/132"}, {"key": "C", "text": "50/132"}, {"key": "D", "text": "32/55"}, {"key": "E", "text": "35/55"}], "assets_patch": {"html": "<table><thead><tr><th>Annual salary ($1,000)</th><th>[5, 7)</th><th>[7, 9)</th><th>[9, 11)</th><th>[11, 13)</th><th>[13, 15)</th></tr></thead><tbody><tr><th>Men</th><td>45</td><td>25</td><td>30</td><td>20</td><td>12</td></tr><tr><th>Women</th><td>15</td><td>20</td><td>10</td><td>15</td><td>8</td></tr></tbody></table>"}}, "explanation": "There are 20 + 12 = 32 men in the salary groups starting at $11,000. The selection is from all 200 employees, so the probability is 32/200 = 4/25.", "correct": "A"}, {"id": "c3716f84-305b-4ecf-9594-481f95c9360f", "before": {"stem": "Question 30. One employee is randomly selected from the company. What is the probability that\n the employee is a man with an annual salary of at least $11,000?", "choices": [{"key": "A", "text": "4\n 25"}, {"key": "B", "text": "32\n 132"}, {"key": "C", "text": "50\n 132"}, {"key": "D", "text": "32\n 55"}, {"key": "E", "text": "35\n 55"}], "correct": "A", "explanation": "The male employees earning at least $11,000 are 20 in [11,13) and 12 in [13,15), or 32 out of 200 employees. Probability 32/200=4/25."}, "source_question_id": "est2_hs_level1_jan_2026-q00030", "source": "ESTII-HS Math L1 January 2026 Q30; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": false, "fields": {"stem": "The table gives annual salaries for all 200 employees in a company. One employee is selected at random. What is the probability that the employee is a man earning at least $11,000 per year?", "choices": [{"key": "A", "text": "4/25"}, {"key": "B", "text": "32/132"}, {"key": "C", "text": "50/132"}, {"key": "D", "text": "32/55"}, {"key": "E", "text": "35/55"}], "assets_patch": {"html": "<table><thead><tr><th>Annual salary ($1,000)</th><th>[5, 7)</th><th>[7, 9)</th><th>[9, 11)</th><th>[11, 13)</th><th>[13, 15)</th></tr></thead><tbody><tr><th>Men</th><td>45</td><td>25</td><td>30</td><td>20</td><td>12</td></tr><tr><th>Women</th><td>15</td><td>20</td><td>10</td><td>15</td><td>8</td></tr></tbody></table>"}}, "explanation": "There are 20 + 12 = 32 men in the salary groups starting at $11,000. The selection is from all 200 employees, so the probability is 32/200 = 4/25.", "correct": "A", "duplicate_of": "a35f72ba-7401-6ab9-98fa-2ff0adeca6e8"}, {"id": "852edbdc-ff69-beb8-d152-a4fe99cb7ece", "before": {"stem": "Question 31. The HR department is organizing a race featuring five employees, each\n representing a different salary class. The probability that the representative of the\n first salary class wins is 𝑝. As the salary class goes up, the probability of winning\n is halved. What is the probability that the employee representing the [5 −7) class\n wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4\n 5"}, {"key": "C", "text": "16\n 31"}, {"key": "D", "text": "1\n 2"}, {"key": "E", "text": "8\n 31\n\n 13\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "The five classes have win probabilities p,p/2,p/4,p/8,p/16, totaling (31/16)p=1. The requested [5,7) class is the first class in the printed salary table, so p=16/31."}, "source_question_id": "est2_hs_level1_jan_2026-q00291", "source": "ESTII-HS Math L1 January 2026 Q31; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "A race has five employees, one from each salary class: [5, 7), [7, 9), [9, 11), [11, 13), and [13, 15) thousand dollars. Exactly one employee wins. The first-class representative wins with probability p, and each successive class has half the preceding probability. What is the probability that the representative of the [5, 7) class wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4/5"}, {"key": "C", "text": "16/31"}, {"key": "D", "text": "1/2"}, {"key": "E", "text": "8/31"}]}, "explanation": "The five mutually exclusive winning probabilities add to 1: \\(p+p/2+p/4+p/8+p/16=31p/16=1\\). The requested class is the first, so its probability is \\(p=16/31\\).", "correct": "C"}, {"id": "c02f7507-92d3-f33e-4ded-994ed325ba84", "before": {"stem": "Question 31. The HR department is organizing a race featuring five employees, each\n representing a different salary class. The probability that the representative of the\n first salary class wins is 𝑝. As the salary class goes up, the probability of winning\n is halved. What is the probability that the employee representing the [5 −7) class\n wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4\n 5"}, {"key": "C", "text": "16\n 31"}, {"key": "D", "text": "1\n 2"}, {"key": "E", "text": "8\n 31\n\n 13\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "The five classes have win probabilities p,p/2,p/4,p/8,p/16, totaling (31/16)p=1. The requested [5,7) class is the first class in the printed salary table, so p=16/31."}, "source_question_id": "est2_hs_level1_jan_2026-q00031", "source": "ESTII-HS Math L1 January 2026 Q31; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": false, "fields": {"stem": "A race has five employees, one from each salary class: [5, 7), [7, 9), [9, 11), [11, 13), and [13, 15) thousand dollars. Exactly one employee wins. The first-class representative wins with probability p, and each successive class has half the preceding probability. What is the probability that the representative of the [5, 7) class wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4/5"}, {"key": "C", "text": "16/31"}, {"key": "D", "text": "1/2"}, {"key": "E", "text": "8/31"}]}, "explanation": "The five mutually exclusive winning probabilities add to 1: \\(p+p/2+p/4+p/8+p/16=31p/16=1\\). The requested class is the first, so its probability is \\(p=16/31\\).", "correct": "C", "duplicate_of": "852edbdc-ff69-beb8-d152-a4fe99cb7ece"}, {"id": "27d369d4-a4d4-cd6f-2eae-843c9978731e", "before": {"stem": "Question 36. Samir has a number of marbles between 300 and 350. When the marbles are\n divided into groups of 12 or groups of 18, there are always 3 marbles left. How\n many marbles does Samir have?", "choices": [{"key": "A", "text": "350"}, {"key": "B", "text": "329"}, {"key": "C", "text": "327"}, {"key": "D", "text": "324"}, {"key": "E", "text": "291\n\n 15\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "N-3 is divisible by lcm(12,18)=36. Between 300 and 350 the only such N is 36*9+3=327."}, "source_question_id": "est2_hs_level1_jan_2026-q00296", "source": "ESTII-HS Math L1 January 2026 Q36; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Samir has between 300 and 350 marbles. Dividing them into groups of 12 or groups of 18 always leaves 3 marbles. How many does he have?", "choices": [{"key": "A", "text": "350"}, {"key": "B", "text": "329"}, {"key": "C", "text": "327"}, {"key": "D", "text": "324"}, {"key": "E", "text": "291"}]}, "explanation": "The number minus 3 must be divisible by both 12 and 18, hence by their least common multiple, 36. The only multiple of 36 between 297 and 347 is 324. Therefore the number of marbles is 324 + 3 = 327. Check: 327 = 12×27 + 3 = 18×18 + 3.", "correct": "C"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;

