DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "07691b4d-a501-d076-8818-3cd9557a401d", "before": {"stem": "Q39. Ahmed types 10 words per 60 seconds. How many whole words can he type in\n 1 min 20 sec?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "3"}, {"key": "C", "text": "13"}, {"key": "D", "text": "14\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 41"}], "correct": "C", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00186", "source": "ghoneem_full_revision_jun_2026; source page 41", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "3"}, {"key": "C", "text": "13"}, {"key": "D", "text": "14"}]}, "explanation": "Each complete word takes 60/10 = 6 seconds. In 80 seconds Ahmed can complete floor(80/6) = 13 words. The fourteenth word would need 84 seconds.", "correct": "C"}, {"id": "077dc3dd-a092-e431-e6ab-c082327c0dc4", "before": {"stem": "Q82. If f(x) = x³ − 3x and g(x) = x − 4, then f(g(1)) =", "choices": [{"key": "A", "text": "−27"}, {"key": "B", "text": "−21"}, {"key": "C", "text": "−18"}, {"key": "D", "text": "−12\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 17"}], "correct": "C", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00081", "source": "ghoneem_full_revision_jun_2026; source page 17", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "−27"}, {"key": "B", "text": "−21"}, {"key": "C", "text": "−18"}, {"key": "D", "text": "−12"}]}, "explanation": "First g(1) = 1 − 4 = −3. Then f(−3) = (−3)³ − 3(−3) = −27 + 9 = −18.", "correct": "C"}, {"id": "0b45e837-d775-62cd-b64b-7928f1936002", "before": {"stem": "Q19. An apartment costs $150,000 to buy. Renting it costs $900 per month plus\n $100 in monthly fees. If x is the number of months of stay, for which values of x is\n buying less expensive than renting?", "choices": [{"key": "A", "text": "x < 150"}, {"key": "B", "text": "x > 150"}, {"key": "C", "text": "x < 166"}, {"key": "D", "text": "x > 166\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 5"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00019", "source": "ghoneem_full_revision_jun_2026; source page 5", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "x < 150"}, {"key": "B", "text": "x > 150"}, {"key": "C", "text": "x < 166"}, {"key": "D", "text": "x > 166"}]}, "explanation": "Renting costs 900 + 100 = $1,000 per month. Buying is cheaper when 150,000 < 1,000x, or x > 150. At 150 months the costs are equal.", "correct": "B"}, {"id": "17bc25c6-2c07-3956-3320-53bfb3781715", "before": {"stem": "Question 12. The graph of function 𝑓 defined by 𝑓(𝑥) = −𝑥+1 and the straight line 𝐷 with\n 𝑥2\n equation 𝑦= 𝑥−1 intersect at point 𝐼. The coordinates of 𝐼 are:", "choices": [{"key": "A", "text": "(1, −1)"}, {"key": "B", "text": "(1, 0)"}, {"key": "C", "text": "(1, 1)"}, {"key": "D", "text": "(−1, −2)"}, {"key": "E", "text": "(−1, −1)\n\n 5\nESTII-HS Math L1 January 2026"}], "correct": "B", "explanation": "At x=1 the printed function (1-x)/x^2 equals 0 and the line y=x-1 also equals 0. The only real intersection is (1,0)."}, "source_question_id": "est2_hs_level1_jan_2026-q00272", "source": "est2_hs_level1_jan_2026; source page 170", "review_note": "Original January 2026 page 5 visually checked; restored fraction grouping and removed footer.", "release": true, "fields": {"choices": [{"key": "A", "text": "(1, −1)"}, {"key": "B", "text": "(1, 0)"}, {"key": "C", "text": "(1, 1)"}, {"key": "D", "text": "(−1, −2)"}, {"key": "E", "text": "(−1, −1)"}], "stem": "The graphs of f(x) = (1 − x)/x² and y = x − 1 intersect at point I. What are the coordinates of I?"}, "explanation": "Equate (1 − x)/x² to x − 1 with x ≠ 0. Multiplying by x² gives −(x − 1) = x²(x − 1), so (x − 1)(x² + 1) = 0. The only real solution is x = 1; then y = 0.", "correct": "B"}, {"id": "1b19298c-3e41-5583-bcc8-749ae32c4ecc", "before": {"stem": "A deck of 52 play cards includes (Diamonds,\nSpades, Clubs, and Hearts).Each group contains 4\ncards (Aces, Queens, King, Jacks)..From the same\ndeck, if one card is drawn without replacement,\nwhat is the probability that it is a Spade?", "choices": [{"key": "A", "text": "1/13"}, {"key": "B", "text": "1/17"}, {"key": "C", "text": "I1/4"}, {"key": "D", "text": "1/26\n22- data set with mean of 100 and sum=3000\nfind the number of values in the data set."}], "correct": "C", "explanation": "Independently solved and checked against the original scanned page and printed choices."}, "source_question_id": "revision_2_march_2026-p44-q56", "source": "revision_2_march_2026; source page 44", "review_note": "Removed the false four-cards-per-suit statement and unrelated next-question text. The standard-deck count gives 13/52.", "release": true, "fields": {"choices": [{"key": "A", "text": "1/13"}, {"key": "B", "text": "1/17"}, {"key": "C", "text": "1/4"}, {"key": "D", "text": "1/26"}], "stem": "One card is drawn at random from a standard 52-card deck. What is the probability that it is a spade?"}, "explanation": "A standard 52-card deck contains 13 spades. Thus P(spade) = 13/52 = 1/4.", "correct": "C"}, {"id": "3e9a1f8d-ac79-065d-efe6-17cc7fbd23a8", "before": {"stem": "A deck of 52 play cards includes (Diamonds,\nSpades, Clubs, and Hearts).Each group contains 4\ncards (Aces, Queens, King, Jacks)..From the same\ndeck, if one card is drawn without replacement,\nwhat is the probability that it is a Spade?", "choices": [{"key": "A", "text": "1/13"}, {"key": "B", "text": "1/17"}, {"key": "C", "text": "1/4"}, {"key": "D", "text": "1/26\n22- data set with mean of 100 and sum=3000\nfind the number of values in the data set."}], "correct": "C", "explanation": "Independently solved and checked against the original scanned page and printed choices."}, "source_question_id": "revision_2_june_2026_a-p44-q51", "source": "revision_2_june_2026_a; source page 44", "review_note": "Removed the false four-cards-per-suit statement and unrelated next-question text. The standard-deck count gives 13/52.", "release": true, "fields": {"choices": [{"key": "A", "text": "1/13"}, {"key": "B", "text": "1/17"}, {"key": "C", "text": "1/4"}, {"key": "D", "text": "1/26"}], "stem": "One card is drawn at random from a standard 52-card deck. What is the probability that it is a spade?"}, "explanation": "A standard 52-card deck contains 13 spades. Thus P(spade) = 13/52 = 1/4.", "correct": "C"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
