DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "642f1f4f-e2e3-ceaa-29dc-928acf7f57a5", "before": {"stem": "Q139. T is a right isosceles triangle with hypotenuse 9√2, and T′ is a 30°–60°–90°\n triangle whose short leg equals 4. What is the sum of the perimeters of both\n triangles (nearest tenth)?", "choices": [{"key": "A", "text": "49.7"}, {"key": "B", "text": "34.5"}, {"key": "C", "text": "54.4"}, {"key": "D", "text": "38.5\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 27"}], "correct": "A", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00135", "source": "ghoneem_full_revision_jun_2026; source page 27", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "49.7"}, {"key": "B", "text": "34.5"}, {"key": "C", "text": "54.4"}, {"key": "D", "text": "38.5"}]}, "explanation": "The 45–45–90 triangle has legs 9 and 9, so its perimeter is 18 + 9√2. The 30–60–90 triangle has sides 4, 4√3, and 8, so its perimeter is 12 + 4√3. Their sum is 30 + 9√2 + 4√3 ≈ 49.655, which rounds to 49.7.", "correct": "A"}, {"id": "65e2e369-c648-8ac5-8e5d-06b30357ef85", "before": {"stem": "Q133. A rectangle's length is 3 units more than its width, and its area is 54 sq\n units. Let width = x. Which statements are true? I: x² + 3x = 54. II: 2x + 3 = √225.\n III: The width is 6 units. IV: The perimeter is 30 units.", "choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "II only"}, {"key": "C", "text": "I, II, and III only"}, {"key": "D", "text": "All statements are true\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 26"}], "correct": "D", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00130", "source": "ghoneem_full_revision_jun_2026; source page 26", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "II only"}, {"key": "C", "text": "I, II, and III only"}, {"key": "D", "text": "All statements are true"}]}, "explanation": "The area equation is x(x + 3) = 54. Factoring gives (x + 9)(x − 6) = 0, and positive width x = 6. The length is 9. Therefore 2x + 3 = 15 = √225 and the perimeter is 2(6 + 9) = 30. All four statements are true.", "correct": "D"}, {"id": "674acd5c-89d7-4029-71d4-dcfcb81a8e9a", "before": {"stem": "Q62. The price of a stock on day t (1 ≤ t ≤ 15) is modeled by p(t) = −t² + 14t + k,\n where k is a constant. On what day was the price equal to the price on day 3?", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "11"}, {"key": "C", "text": "13"}, {"key": "D", "text": "15\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 13"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00061", "source": "ghoneem_full_revision_jun_2026; source page 13", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "11"}, {"key": "C", "text": "13"}, {"key": "D", "text": "15"}], "stem": "For 1 ≤ t ≤ 15, a stock price is modeled by p(t) = −t² + 14t + k. On which other day was its price the same as on day 3?"}, "explanation": "The symmetry axis of p(t) = −t² + 14t + k is t = 7. The day symmetric to day 3 is 2(7) − 3 = 11. Equivalently p(t) = p(3) gives (t − 3)(t − 11) = 0.", "correct": "B"}, {"id": "68f82a1f-f2a9-b20c-947d-cccfffe8930c", "before": {"stem": "Q5. The average height of 11 players is 192 cm. After a new player joins, the\n average becomes 196.4 cm. What is the new player's height?", "choices": [{"key": "A", "text": "232.4"}, {"key": "B", "text": "244.8"}, {"key": "C", "text": "196.4"}, {"key": "D", "text": "252\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 35"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00153", "source": "ghoneem_full_revision_jun_2026; source page 35", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "232.4"}, {"key": "B", "text": "244.8"}, {"key": "C", "text": "196.4"}, {"key": "D", "text": "252"}]}, "explanation": "The original total is 11 × 192 = 2112 cm. The new total is 12 × 196.4 = 2356.8 cm. The new player is 2356.8 − 2112 = 244.8 cm tall.", "correct": "B"}, {"id": "6a931193-a8d6-9382-adbb-278932477c77", "before": {"stem": "18.\n The scatter plot shows the relationship between weight (x) in kilograms and height (y) in centimeters for a group\n of students.\n What will be the height if the weight is 190?", "choices": [{"key": "A", "text": "100"}, {"key": "B", "text": "572"}, {"key": "C", "text": "50"}, {"key": "D", "text": "180\n\n 5"}], "correct": "B", "explanation": "Using the line of best fit y = 3x + 2.2 at x = 190 gives 572.2, for which the listed rounded answer is 572. This extrapolation is far outside the plotted range."}, "source_question_id": "est1_dec_2025-q00017", "source": "est1_dec_2025; source page 5", "review_note": "Restored the displayed line-of-best-fit equation; kept the source input 190 and explicitly identified the result as a rounded extrapolation.", "release": true, "fields": {"choices": [{"key": "A", "text": "100"}, {"key": "B", "text": "572"}, {"key": "C", "text": "50"}, {"key": "D", "text": "180"}], "stem": "The line of best fit for height y, in centimeters, versus weight x, in kilograms, is y = 3x + 2.2. According to this model, what is the predicted height when x = 190, to the nearest centimeter?"}, "explanation": "Substitute x = 190 into the stated best-fit model: y = 3(190) + 2.2 = 572.2. Rounded to the nearest centimeter, this is 572. It is an extrapolated model prediction, not a measured height.", "correct": "B"}, {"id": "6d2a0a90-f555-71aa-3b33-12c7d2f818bf", "before": {"stem": "44. A customer pays a total of $880 for 4 headphones plus a $12 fixed\n delivery fee. If the customer wants to buy 6 headphones, what is the\n total amount he would pay ?", "choices": [{"key": "A", "text": "1302"}, {"key": "B", "text": "1314"}, {"key": "C", "text": "1332"}, {"key": "D", "text": "1343\n\n 11"}], "correct": "B", "explanation": "The unit price is (880 - 12)/4 = 217. Six units plus the fixed $12 fee cost 6(217) + 12 = $1,314."}, "source_question_id": "est1_dec_2025-q00040", "source": "est1_dec_2025; source page 11", "review_note": "Removed page-footer contamination; independently solved the complete problem and checked every choice.", "release": true, "fields": {"choices": [{"key": "A", "text": "1302"}, {"key": "B", "text": "1314"}, {"key": "C", "text": "1332"}, {"key": "D", "text": "1343"}]}, "explanation": "Subtract the one-time delivery charge: 880 − 12 = $868 for four headphones, so each costs 868/4 = $217. Six headphones with the same delivery fee cost 6(217) + 12 = $1,314.", "correct": "B"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
